import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { parseDocument, stringify } from 'yaml';
import { DOCUMENT_ID_PREFIX, DOCUMENT_ROOT } from './documents-contract.js';
import { configV2Schema, FILESYSTEM_DOCUMENT_TOOLS, FILESYSTEM_ISSUE_TOOLS, formatSchemaError } from './schemas.js';

export type ConfigDocument = Record<string, unknown>;

export class ConfigError extends Error {
  public constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

const CONFIG_PATH = join('.harnessctl', 'config.yaml');
export const DEFAULT_CONFIG: ConfigDocument = {
  version: 2,
  issues: {
    root: '.harnessctl/issues',
    prefix: 'hrn-',
    type: 'filesystem',
    tools: FILESYSTEM_ISSUE_TOOLS,
  },
  documents: {
    root: DOCUMENT_ROOT,
    prefix: DOCUMENT_ID_PREFIX,
    type: 'filesystem',
    tools: FILESYSTEM_DOCUMENT_TOOLS,
  },
  cvs: {
    local: 'git',
    remote: {
      provider: 'github',
      tools: 'gh',
      url: 'https://github.com',
      token_env: 'GH_TOKEN',
    },
  },
  mcp: { output_limit_mode: 'bounded-guidance', web_retrieval: { enabled: false } },
  skills: {
    'sdlc-code-index': { enabled: false, mcp_server: 'sdlc-code-index' },
  },
  paths: {
    root: '.harnessctl',
    tasks: '.harnessctl/tasks',
    reports: '.harnessctl/reports',
  },
  workflow: {
    default_task_type: 'bug',
    tdd: { enabled: false },
  },
  communication: {
    caveman: { enabled: true, mode: 'strict' },
  },
  memory: {
    enabled: false,
    backend: 'repository',
    namespace: {
      organization_id: 'local',
      project_id: 'project',
      default_topic: 'general',
    },
    retrieval: { limit: 8, max_chars: 12_000, include_superseded: false },
    repository: {
      root: '.harnessctl/memory',
    },
  },
};

function configPath(cwd: string): string {
  return join(cwd, CONFIG_PATH);
}

function assertConfigDocument(value: unknown): ConfigDocument {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    throw new ConfigError('Configuration root must be a YAML mapping.');
  }

  return value as ConfigDocument;
}

function assertStringMappingKeys(value: unknown, seen = new Set<object>()): void {
  if (value === null || typeof value !== 'object' || seen.has(value)) return;
  seen.add(value);

  if (value instanceof Map) {
    for (const [key, nested] of value) {
      if (typeof key !== 'string') throw new ConfigError('Malformed YAML: mapping keys must be strings.');
      assertStringMappingKeys(nested, seen);
    }
    return;
  }
  if (Array.isArray(value)) {
    for (const nested of value) assertStringMappingKeys(nested, seen);
  }
}

export function parseConfig(content: string): ConfigDocument {
  const document = parseDocument(content);
  if (document.errors.length > 0) {
    const error = document.errors[0];
    const position = error?.linePos?.[0];
    const location = position === undefined ? '' : ` at line ${position.line}, column ${position.col}`;
    throw new ConfigError(`Malformed YAML: ${error?.code ?? 'PARSE_ERROR'}${location}.`);
  }

  assertStringMappingKeys(document.toJS({ mapAsMap: true }));
  return validateAndMigrateConfig(assertConfigDocument(document.toJS()));
}

export function validateAndMigrateConfig(value: ConfigDocument): ConfigDocument {
  const version = value.version;
  if (version !== undefined && version !== 1 && version !== 2)
    throw new ConfigError(`Unsupported configuration version: ${String(version)}`);
  if (Object.prototype.hasOwnProperty.call(value, 'code_index'))
    throw new ConfigError(
      'Invalid configuration: code_index is no longer supported; configure skills.sdlc-code-index instead.',
    );
  if (isMapping(value.mcp) && Object.prototype.hasOwnProperty.call(value.mcp, 'servers'))
    throw new ConfigError(
      'Invalid configuration: mcp.servers is no longer supported; configure skills.sdlc-code-index and manage external MCP servers in the host configuration.',
    );

  assertRemoteConfigurationExplicit(value);
  assertFixedDocumentConfiguration(value.documents);
  const config = deepMerge(DEFAULT_CONFIG, value);
  config.version = 2;
  normalizeIssueTools(config);
  normalizeDocumentTools(config);
  normalizeCvsTools(config);
  const result = configV2Schema.safeParse(config);
  if (!result.success) throw new ConfigError(`Invalid configuration:\n${formatSchemaError(result.error)}`);
  return result.data;
}

const REMOTE_ISSUE_TYPES = new Set(['github', 'gitlab', 'gitea', 'forgejo']);
const EXPECTED_PROVIDER_TOOL: Readonly<Record<string, string>> = {
  github: 'gh',
  gitlab: 'glab',
  gitea: 'tea',
  forgejo: 'forgejo-cli',
};
function assertRemoteConfigurationExplicit(value: ConfigDocument): void {
  const issues = value.issues;
  if (isMapping(issues) && REMOTE_ISSUE_TYPES.has(String(issues.type))) {
    if (!Object.prototype.hasOwnProperty.call(issues, 'tools'))
      throw new ConfigError(
        `Invalid configuration: issues.type=${String(issues.type)} requires issues.tools to be selected explicitly.`,
      );
    if (!Object.prototype.hasOwnProperty.call(issues, 'remote'))
      throw new ConfigError(`Invalid configuration: issues.type=${String(issues.type)} requires issues.remote.`);
  }

  const cvs = value.cvs;
  if (!isMapping(cvs) || !isMapping(cvs.remote)) return;
  const provider = cvs.remote.provider;
  if (provider === undefined || provider === 'github') return;
  for (const key of ['tools', 'url', 'token_env']) {
    if (!Object.prototype.hasOwnProperty.call(cvs.remote, key))
      throw new ConfigError(
        `Invalid configuration: cvs.remote.provider=${String(provider)} requires cvs.remote.${key} to be selected explicitly.`,
      );
  }
}

function assertFixedDocumentConfiguration(value: unknown): void {
  if (value === undefined) return;
  if (!isMapping(value)) throw new ConfigError('Invalid configuration: documents must be a mapping.');
  if (
    Object.prototype.hasOwnProperty.call(value, 'remote') ||
    (value.type !== undefined && value.type !== 'filesystem')
  )
    throw new ConfigError(
      'Invalid configuration: remote Documents providers were removed; use the repository-local .harnessctl/documents authority.',
    );
  if (value.root !== undefined && value.root !== DOCUMENT_ROOT)
    throw new ConfigError(`Invalid configuration: documents.root is fixed to ${DOCUMENT_ROOT}.`);
  if (value.prefix !== undefined && value.prefix !== DOCUMENT_ID_PREFIX)
    throw new ConfigError(`Invalid configuration: documents.prefix is fixed to ${DOCUMENT_ID_PREFIX}.`);
}

function normalizeCvsTools(config: ConfigDocument): void {
  const cvs = config.cvs;
  if (!isMapping(cvs) || !isMapping(cvs.remote) || typeof cvs.remote.tools !== 'string') return;
  const tools = parseToolIdentifiers(cvs.remote.tools, 'cvs.remote.tools');
  const expected = EXPECTED_PROVIDER_TOOL[String(cvs.remote.provider)];
  if (expected !== undefined && (tools.length !== 1 || tools[0] !== expected))
    throw new ConfigError(
      `Invalid configuration: cvs.remote.tools must be exactly ${expected} for cvs.remote.provider=${String(cvs.remote.provider)}.`,
    );
  if (expected !== undefined) cvs.remote.tools = expected;
}

function normalizeIssueTools(config: ConfigDocument): void {
  const issues = config.issues;
